export interface Event {
  id: number;
  type: string;
  timestamp: Date;
  data: any;
}

export interface MetricRequest {
  name: string;
  aggregationType?: 'average' | 'sum' | 'count';
  timeframe?: 'hourly' | 'daily' | 'weekly' | 'monthly';
  queryParams?: {
    userId?: number;
    productCode?: string;
  };
}

export interface AggregateQuery {
  itemId: number;
  metricName: string;
  aggregationType: 'average' | 'sum' | 'count' | undefined;
  timeframe: 'hourly' | 'daily' | 'weekly' | 'monthly';
}

export enum EventStoreError {
  DatabaseError = 'DATABASE_ERROR',
  SchemaValidationFailed = 'SCHEMA_VALIDATION_FAILED',
}

export type EventStoreResult<T> = T | null | Error | Promise<EventStoreResult<T>>;

export function storeEvent(event: Event): EventStoreResult<void> {
  const events: Event[] = [];
  events.push(event);
  return null;
}

export function getMetricRequest(request: MetricRequest): EventStoreResult<MetricRequest> {
  const requests: MetricRequest[] = [];
  const foundRequest = requests.find((req) => req.name === request.name);
  return foundRequest !== undefined ? foundRequest : null;
}

export function aggregateEvents(query: AggregateQuery): EventStoreResult<number> {
  const events: Event[] = [];
  const filteredEvents = events.filter((e) => e.type === query.metricName);
  const avgActivityTime = filteredEvents.reduce((acc, evt) => acc + (evt.timestamp.getTime() - 1000), 0) / filteredEvents.length;
  return avgActivityTime;
}

