export function render(container: HTMLElement) {
    const kpiCards = [
        { title: 'Total Users', value: 5200, trend: 'up', color: '#4ade80' },
        { title: 'Active Sessions', value: 345, trend: 'up', color: '#60a5fa' },
        { title: 'Revenue', value: '$45,000', trend: 'up', color: '#f87171' },
        { title: 'Conversion Rate', value: '23.4%', trend: 'up', color: '#f472b6' },
        { title: 'Avg. Session Time', value: '15.2 min', trend: 'up', color: '#a78bfa' },
    ];

    const kpiContainer = document.createElement('div');
    kpiContainer.style.display = 'flex';
    kpiContainer.style.flexDirection = 'column';
    kpiContainer.style.gap = '8px';

    kpiCards.forEach(card => {
        const cardEl = document.createElement('div');
        cardEl.style.background = '#151524';
        cardEl.style.border = '1px solid rgba(255,255,255,0.1)';
        cardEl.style.borderRadius = '8px';
        cardEl.style.padding = '12px 16px';
        cardEl.style.fontSize = '0.85rem';
        cardEl.style.color = '#e0e0f0';
        cardEl.style.minHeight = '60px';

        cardEl.innerHTML = `
            <div style="font-weight: 600; font-size: 0.9rem">${card.title}</div>
            <div style="font-size: 1.2rem; font-weight: 700">${card.value}</div>
            <div style="font-size: 0.7rem; margin-top: 4px">${card.trend === 'up' ? '▲' : '▼'} ${card.trend}</div>
        `;

        kpiContainer.appendChild(cardEl);
    });

    const overview = document.createElement('div');
    overview.style.display = 'flex';
    overview.style.flexDirection = 'column';
    overview.style.alignItems = 'center';
    overview.style.gap = '16px';
    overview.style.padding = '24px';

    const title = document.createElement('div');
    title.style.fontSize = '1.2rem';
    title.style.fontWeight = '600';
    title.style.color = '#00d9ff';
    title.textContent = '📊 Analytics Dashboard';

    const summary = document.createElement('div');
    summary.style.display = 'flex';
    summary.style.gap = '16px';
    summary.style.flexWrap = 'wrap';

    kpiCards.forEach(card => {
        const badge = document.createElement('div');
        badge.style.background = card.color;
        badge.style.color = '#00d9ff';
        badge.style.padding = '4px 12px';
        badge.style.borderRadius = '4px';
        badge.style.fontSize = '0.8rem';
        badge.style.fontWeight = '600';
        badge.style.display = 'flex';
        badge.style.alignItems = 'center';
        badge.style.gap = '4px';
        badge.textContent = `${card.value} ${card.title}`;
        summary.appendChild(badge);
    });

    overview.appendChild(title);
    overview.appendChild(summary);
    overview.appendChild(kpiContainer);

    container.appendChild(overview);
}

