import { Event, MetricRequest, AggregateQuery, EventStoreError, EventStoreResult, storeEvent, getMetricRequest, aggregateEvents } from '../event-models/event-models.ts';

export function aggregateData(items: { name: string; value: number }[]): number {
    let total = 0;
    for (const item of items) {
        total += item.value;
    }
    return total;
}

export function getTopItems(items: { name: string; value: number }[], limit: number): { name: string; value: number }[] {
    return items.sort((a, b) => b.value - a.value).slice(0, limit);
}

export function calculateKPIs(data: { [key: string]: number }, metrics: { name: string; formula: string }[]): { [key: string]: number } {
    const kpis: { [key: string]: number } = {};
    for (const metric of metrics) {
        kpis[metric.name] = evaluateFormula(metric.formula, data);
    }
    return kpis;
}

function evaluateFormula(formula: string, data: { [key: string]: number }): number {
    try {
        const tokens = tokenizeFormula(formula);
        return evaluateTokens(tokens, data);
    } catch (error) {
        console.error('Failed to evaluate formula:', formula, error);
        return 0;
    }
}

function tokenizeFormula(formula: string): string[] {
    return formula.split(' ').filter(token => token);
}

function evaluateTokens(tokens: string[], data: { [key: string]: number }): number {
    if (tokens.length === 0) return 0;
    let result = parseFloat(tokens[0]);
    for (let i = 1; i < tokens.length; i += 2) {
        const operator = tokens[i];
        const value = parseFloat(tokens[i + 1]);
        if (operator === '+') result += value;
        else if (operator === '-') result -= value;
        else if (operator === '*') result *= value;
        else if (operator === '/') result /= value;
    }
    return result;
}

